#include <cstddef>
#include <vector>
#include <iostream>

void process_vector(const std::vector<int>& v) {
    // size_t for element count
    std::cout << "Size: " << v.size() << std::endl;

    // ptrdiff_t for distance calculation
    if (v.size() > 1) {
        auto it1 = v.begin();
        auto it2 = v.end() - 1;
        std::ptrdiff_t diff = it2 - it1;
        std::cout << "Distance: " << diff << std::endl;
    }
}

int main() {
    std::vector<int> data(10);
    process_vector(data);
}
